# RSA-1024
# Given values
e = 65537
lower, upper = 1 << 15, (1 << 16) - 1
while True:
    p = randprime(lower, upper)
    q = randprime(lower, upper)
    if p == q: 
        continue
    phi = (p - 1) * (q - 1)
    if math.gcd(e, phi) == 1:
        n = p * q
        d = inverse(e, phi)
assert isprime(p) and isprime(q)
assert p * q == n
# Encrypt 
m = bytes_to_long(b"THM{Psssss_4nd_Qsssssss}") 
c = pow(m, e, n)
print(f"c = {c}")

# Decrypt
m2 = pow(c, e, n)
flag = long_to_bytes(m2)
print(flag.decode('utf-8', errors='ignore'))
